//! Arena-backed storage for the polygon ring nodes.
//!
//! The C++ original hands out raw `Node*` out of an object pool and relies on
//! the pool keeping every node alive until the triangulation is finished. Here
//! the nodes live in a `Vec` and are referred to by their index, so `NONE`
//! plays the role of a null pointer.

use std::ops::{Index, IndexMut};

/// Index value standing in for a null `Node*`.
pub const NONE: usize = usize::MAX;

#[derive(Clone, Copy, Debug)]
pub struct Node {
    /// Index of the vertex in the flattened input coordinate list.
    pub i: u32,
    pub x: f64,
    pub y: f64,

    /// Previous and next vertex nodes in a polygon ring.
    pub prev: usize,
    pub next: usize,

    /// Z-order curve value.
    pub z: i32,

    /// Previous and next nodes in z-order.
    pub prev_z: usize,
    pub next_z: usize,

    /// Indicates whether this is a steiner point.
    pub steiner: bool,
}

impl Node {
    fn new(i: u32, x: f64, y: f64) -> Self {
        Node {
            i,
            x,
            y,
            prev: NONE,
            next: NONE,
            z: 0,
            prev_z: NONE,
            next_z: NONE,
            steiner: false,
        }
    }
}

pub struct Arena {
    nodes: Vec<Node>,
}

impl Arena {
    pub fn new() -> Self {
        Arena { nodes: Vec::new() }
    }

    /// Drops every node and pre-allocates room for `capacity` new ones.
    pub fn reset(&mut self, capacity: usize) {
        self.nodes.clear();
        self.nodes.reserve(capacity);
    }

    pub fn clear(&mut self) {
        self.nodes.clear();
        self.nodes.shrink_to_fit();
    }

    /// Allocates a node and returns its handle.
    pub fn construct(&mut self, i: u32, x: f64, y: f64) -> usize {
        self.nodes.push(Node::new(i, x, y));
        self.nodes.len() - 1
    }
}

impl Index<usize> for Arena {
    type Output = Node;

    #[inline]
    fn index(&self, i: usize) -> &Node {
        &self.nodes[i]
    }
}

impl IndexMut<usize> for Arena {
    #[inline]
    fn index_mut(&mut self, i: usize) -> &mut Node {
        &mut self.nodes[i]
    }
}

