//! A `std`-only ear-clipping triangulator for polygons with holes.
//!
//! Port of the `mapbox::earcut` interface: the input is a list of rings (the
//! first one is the outer ring, the rest are holes) and the output is a flat
//! list of vertex indices, three per triangle, numbered in the order the
//! vertices appear in the concatenated rings.

pub mod nodes;

use nodes::{Arena, NONE};

/// A 2D point, matching `std::array<double, 2>` on the C++ side.
pub type Point = [f64; 2];

/// Triangulates `polygon` and returns the triangle indices.
pub fn earcut(polygon: &[Vec<Point>]) -> Vec<u32> {
    let mut earcut = Earcut::new();
    earcut.run(polygon);
    earcut.indices
}

pub struct Earcut {
    pub indices: Vec<u32>,
    vertices: usize,

    nodes: Arena,

    hashing: bool,
    min_x: f64,
    min_y: f64,
    max_x: f64,
    max_y: f64,
    inv_size: f64,
}

impl Earcut {
    pub fn new() -> Self {
        Earcut {
            indices: Vec::new(),
            vertices: 0,
            nodes: Arena::new(),
            hashing: false,
            min_x: 0.0,
            min_y: 0.0,
            max_x: 0.0,
            max_y: 0.0,
            inv_size: 0.0,
        }
    }

    pub fn run(&mut self, points: &[Vec<Point>]) {
        self.indices.clear();
        self.vertices = 0;

        if points.is_empty() {
            self.nodes.clear();
            return;
        }

        let mut threshold: i32 = 80;
        let mut len: usize = 0;

        let mut i = 0;
        while threshold >= 0 && i < points.len() {
            threshold -= points[i].len() as i32;
            len += points[i].len();
            i += 1;
        }

        // Estimate size of nodes and indices.
        self.nodes.reset(len * 3 / 2);
        self.indices.reserve(len + points[0].len());

        let mut outer_node = self.linked_list(&points[0], true);
        if outer_node == NONE || self.nodes[outer_node].prev == self.nodes[outer_node].next {
            self.nodes.clear();
            return;
        }

        if points.len() > 1 {
            outer_node = self.eliminate_holes(points, outer_node);
        }

        // If the shape is not too simple, we'll use z-order curve hash later;
        // calculate the polygon bbox.
        self.hashing = threshold < 0;
        if self.hashing {
            let mut p = self.nodes[outer_node].next;
            self.min_x = self.nodes[outer_node].x;
            self.max_x = self.min_x;
            self.min_y = self.nodes[outer_node].y;
            self.max_y = self.min_y;
            loop {
                let x = self.nodes[p].x;
                let y = self.nodes[p].y;
                self.min_x = fmin(self.min_x, x);
                self.min_y = fmin(self.min_y, y);
                self.max_x = fmax(self.max_x, x);
                self.max_y = fmax(self.max_y, y);
                p = self.nodes[p].next;
                if p == outer_node {
                    break;
                }
            }

            // min_x, min_y and inv_size are later used to transform coords into
            // integers for the z-order calculation.
            self.inv_size = fmax(self.max_x - self.min_x, self.max_y - self.min_y);
            self.inv_size = if self.inv_size != 0.0 {
                32767.0 / self.inv_size
            } else {
                0.0
            };
        }

        self.earcut_linked(outer_node, 0);

        self.nodes.clear();
    }

    /// Creates a circular doubly linked list from polygon points in the
    /// specified winding order.
    fn linked_list(&mut self, points: &[Point], clockwise: bool) -> usize {
        let len = points.len();
        let mut sum = 0.0;

        // Calculate original winding order of a polygon ring.
        let mut j = if len > 0 { len - 1 } else { 0 };
        for i in 0..len {
            let p1 = points[i];
            let p2 = points[j];
            sum += (p2[0] - p1[0]) * (p1[1] + p2[1]);
            j = i;
        }

        // Link points into a circular doubly linked list in the specified
        // winding order.
        let mut last = NONE;
        if clockwise == (sum > 0.0) {
            for i in 0..len {
                let idx = (self.vertices + i) as u32;
                last = self.insert_node(idx, points[i], last);
            }
        } else {
            for i in (0..len).rev() {
                let idx = (self.vertices + i) as u32;
                last = self.insert_node(idx, points[i], last);
            }
        }

        if last != NONE {
            let next = self.nodes[last].next;
            if self.equals(last, next) {
                self.remove_node(last);
                last = self.nodes[last].next;
            }
        }

        self.vertices += len;

        last
    }

    /// Eliminates colinear or duplicate points.
    fn filter_points(&mut self, start: usize, end: usize) -> usize {
        if start == NONE {
            return start;
        }
        let mut end = if end == NONE { start } else { end };

        let mut p = start;
        let mut again;
        loop {
            again = false;

            let next = self.nodes[p].next;
            let prev = self.nodes[p].prev;
            if !self.nodes[p].steiner && (self.equals(p, next) || self.area(prev, p, next) == 0.0) {
                self.remove_node(p);
                p = self.nodes[p].prev;
                end = p;

                if p == self.nodes[p].next {
                    break;
                }
                again = true;
            } else {
                p = self.nodes[p].next;
            }

            if !(again || p != end) {
                break;
            }
        }

        end
    }

    /// Main ear slicing loop which triangulates a polygon (given as a linked
    /// list).
    fn earcut_linked(&mut self, ear_start: usize, pass: i32) {
        if ear_start == NONE {
            return;
        }
        let mut ear = ear_start;

        // Interlink polygon nodes in z-order.
        if pass == 0 && self.hashing {
            self.index_curve(ear);
        }

        let mut stop = ear;

        // Iterate through ears, slicing them one by one.
        while self.nodes[ear].prev != self.nodes[ear].next {
            let prev = self.nodes[ear].prev;
            let next = self.nodes[ear].next;

            let is_ear = if self.hashing {
                self.is_ear_hashed(ear)
            } else {
                self.is_ear(ear)
            };

            if is_ear {
                // Cut off the triangle.
                self.indices.push(self.nodes[prev].i);
                self.indices.push(self.nodes[ear].i);
                self.indices.push(self.nodes[next].i);

                self.remove_node(ear);

                // Skipping the next vertex leads to less sliver triangles.
                ear = self.nodes[next].next;
                stop = self.nodes[next].next;

                continue;
            }

            ear = next;

            // If we looped through the whole remaining polygon and can't find
            // any more ears.
            if ear == stop {
                if pass == 0 {
                    // Try filtering points and slicing again.
                    let filtered = self.filter_points(ear, NONE);
                    self.earcut_linked(filtered, 1);
                } else if pass == 1 {
                    // If this didn't work, try curing all small
                    // self-intersections locally.
                    let filtered = self.filter_points(ear, NONE);
                    let cured = self.cure_local_intersections(filtered);
                    self.earcut_linked(cured, 2);
                } else if pass == 2 {
                    // As a last resort, try splitting the remaining polygon
                    // into two.
                    self.split_earcut(ear);
                }

                break;
            }
        }
    }

    /// Checks whether a polygon node forms a valid ear with adjacent nodes.
    fn is_ear(&self, ear: usize) -> bool {
        let a = self.nodes[ear].prev;
        let b = ear;
        let c = self.nodes[ear].next;

        if self.area(a, b, c) >= 0.0 {
            return false; // reflex, can't be an ear
        }

        // Now make sure we don't have other points inside the potential ear.
        let (ax, ay) = (self.nodes[a].x, self.nodes[a].y);
        let (bx, by) = (self.nodes[b].x, self.nodes[b].y);
        let (cx, cy) = (self.nodes[c].x, self.nodes[c].y);

        let mut p = self.nodes[self.nodes[ear].next].next;

        while p != self.nodes[ear].prev {
            let prev = self.nodes[p].prev;
            let next = self.nodes[p].next;
            if point_in_triangle(
                ax,
                ay,
                bx,
                by,
                cx,
                cy,
                self.nodes[p].x,
                self.nodes[p].y,
            ) && self.area(prev, p, next) >= 0.0
            {
                return false;
            }
            p = self.nodes[p].next;
        }

        true
    }

    /// Same as [`Earcut::is_ear`], but uses the z-order curve index to only
    /// visit points within the ear's bounding box.
    fn is_ear_hashed(&self, ear: usize) -> bool {
        let a = self.nodes[ear].prev;
        let b = ear;
        let c = self.nodes[ear].next;

        if self.area(a, b, c) >= 0.0 {
            return false; // reflex, can't be an ear
        }

        let (ax, ay) = (self.nodes[a].x, self.nodes[a].y);
        let (bx, by) = (self.nodes[b].x, self.nodes[b].y);
        let (cx, cy) = (self.nodes[c].x, self.nodes[c].y);

        // Triangle bbox; min & max are calculated like this for speed.
        let min_tx = fmin(ax, fmin(bx, cx));
        let min_ty = fmin(ay, fmin(by, cy));
        let max_tx = fmax(ax, fmax(bx, cx));
        let max_ty = fmax(ay, fmax(by, cy));

        // Z-order range for the current triangle bbox.
        let min_z = self.z_order(min_tx, min_ty);
        let max_z = self.z_order(max_tx, max_ty);

        let ear_prev = self.nodes[ear].prev;
        let ear_next = self.nodes[ear].next;

        // First look for points inside the triangle in increasing z-order.
        let mut p = self.nodes[ear].next_z;
        while p != NONE && self.nodes[p].z <= max_z {
            if p != ear_prev && p != ear_next {
                let prev = self.nodes[p].prev;
                let next = self.nodes[p].next;
                if point_in_triangle(ax, ay, bx, by, cx, cy, self.nodes[p].x, self.nodes[p].y)
                    && self.area(prev, p, next) >= 0.0
                {
                    return false;
                }
            }
            p = self.nodes[p].next_z;
        }

        // Then look for points in decreasing z-order.
        p = self.nodes[ear].prev_z;
        while p != NONE && self.nodes[p].z >= min_z {
            if p != ear_prev && p != ear_next {
                let prev = self.nodes[p].prev;
                let next = self.nodes[p].next;
                if point_in_triangle(ax, ay, bx, by, cx, cy, self.nodes[p].x, self.nodes[p].y)
                    && self.area(prev, p, next) >= 0.0
                {
                    return false;
                }
            }
            p = self.nodes[p].prev_z;
        }

        true
    }

    /// Goes through all polygon nodes and cures small local self-intersections.
    fn cure_local_intersections(&mut self, start_in: usize) -> usize {
        let mut start = start_in;
        let mut p = start;
        loop {
            let a = self.nodes[p].prev;
            let pn = self.nodes[p].next;
            let b = self.nodes[pn].next;

            if !self.equals(a, b)
                && self.intersects(a, p, pn, b)
                && self.locally_inside(a, b)
                && self.locally_inside(b, a)
            {
                self.indices.push(self.nodes[a].i);
                self.indices.push(self.nodes[p].i);
                self.indices.push(self.nodes[b].i);

                // Remove the two nodes involved.
                self.remove_node(p);
                let pn = self.nodes[p].next;
                self.remove_node(pn);

                p = b;
                start = b;
            }

            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }

        self.filter_points(p, NONE)
    }

    /// Tries splitting a polygon into two and triangulating them independently.
    fn split_earcut(&mut self, start: usize) {
        // Look for a valid diagonal that divides the polygon into two.
        let mut a = start;
        loop {
            let mut b = self.nodes[self.nodes[a].next].next;
            while b != self.nodes[a].prev {
                if self.nodes[a].i != self.nodes[b].i && self.is_valid_diagonal(a, b) {
                    // Split the polygon in two by the diagonal.
                    let mut c = self.split_polygon(a, b);

                    // Filter colinear points around the cuts.
                    let a_next = self.nodes[a].next;
                    a = self.filter_points(a, a_next);
                    let c_next = self.nodes[c].next;
                    c = self.filter_points(c, c_next);

                    // Run earcut on each half.
                    self.earcut_linked(a, 0);
                    self.earcut_linked(c, 0);
                    return;
                }
                b = self.nodes[b].next;
            }
            a = self.nodes[a].next;
            if a == start {
                break;
            }
        }
    }

    /// Links every hole into the outer loop, producing a single-ring polygon
    /// without holes.
    fn eliminate_holes(&mut self, points: &[Vec<Point>], outer_node_in: usize) -> usize {
        let mut outer_node = outer_node_in;
        let mut queue: Vec<usize> = Vec::new();

        for ring in points.iter().skip(1) {
            let list = self.linked_list(ring, false);
            if list != NONE {
                if list == self.nodes[list].next {
                    self.nodes[list].steiner = true;
                }
                let leftmost = self.get_leftmost(list);
                queue.push(leftmost);
            }
        }

        let xs: Vec<f64> = queue.iter().map(|&n| self.nodes[n].x).collect();
        let mut order: Vec<usize> = (0..queue.len()).collect();
        order.sort_by(|&a, &b| xs[a].partial_cmp(&xs[b]).unwrap_or(std::cmp::Ordering::Equal));
        let queue: Vec<usize> = order.into_iter().map(|i| queue[i]).collect();

        // Process holes from left to right.
        for &hole in &queue {
            self.eliminate_hole(hole, outer_node);
            let next = self.nodes[outer_node].next;
            outer_node = self.filter_points(outer_node, next);
        }

        outer_node
    }

    /// Finds a bridge between vertices that connects a hole with an outer ring
    /// and links it.
    fn eliminate_hole(&mut self, hole: usize, outer_node: usize) {
        let bridge = self.find_hole_bridge(hole, outer_node);
        if bridge != NONE {
            let b = self.split_polygon(bridge, hole);
            let b_next = self.nodes[b].next;
            self.filter_points(b, b_next);
        }
    }

    /// David Eberly's algorithm for finding a bridge between a hole and an
    /// outer polygon.
    fn find_hole_bridge(&self, hole: usize, outer_node: usize) -> usize {
        let mut p = outer_node;
        let hx = self.nodes[hole].x;
        let hy = self.nodes[hole].y;
        let mut qx = f64::NEG_INFINITY;
        let mut m = NONE;

        // Find a segment intersected by a ray from the hole's leftmost vertex
        // to the left; the segment's endpoint with lesser x will be the
        // potential connection vertex.
        loop {
            let next = self.nodes[p].next;
            let py = self.nodes[p].y;
            let ny = self.nodes[next].y;
            if hy <= py && hy >= ny && ny != py {
                let px = self.nodes[p].x;
                let nx = self.nodes[next].x;
                let x = px + (hy - py) * (nx - px) / (ny - py);
                if x <= hx && x > qx {
                    qx = x;
                    m = if px < nx { p } else { next };
                    if x == hx {
                        // Hole touches outer segment; pick the leftmost
                        // endpoint.
                        return m;
                    }
                }
            }
            p = self.nodes[p].next;
            if p == outer_node {
                break;
            }
        }

        if m == NONE {
            return NONE;
        }

        // Look for points strictly inside the triangle of the hole vertex, the
        // segment intersection and the endpoint; if there are no points found,
        // we have a valid connection. Otherwise choose the vertex of the
        // minimum angle with the ray as the connection vertex.
        let stop = m;
        let mut tan_min = f64::INFINITY;
        let mx = self.nodes[m].x;
        let my = self.nodes[m].y;

        p = m;
        loop {
            let px = self.nodes[p].x;
            let py = self.nodes[p].y;
            if hx >= px
                && px >= mx
                && hx != px
                && point_in_triangle(
                    if hy < my { hx } else { qx },
                    hy,
                    mx,
                    my,
                    if hy < my { qx } else { hx },
                    hy,
                    px,
                    py,
                )
            {
                let tan = (hy - py).abs() / (hx - px); // tangential

                if self.locally_inside(p, hole)
                    && (tan < tan_min
                        || (tan == tan_min
                            && (px > self.nodes[m].x || self.sector_contains_sector(m, p))))
                {
                    m = p;
                    tan_min = tan;
                }
            }

            p = self.nodes[p].next;
            if p == stop {
                break;
            }
        }

        m
    }

    /// Whether the sector in vertex `m` contains the sector in vertex `p` in
    /// the same coordinates.
    fn sector_contains_sector(&self, m: usize, p: usize) -> bool {
        let m_prev = self.nodes[m].prev;
        let m_next = self.nodes[m].next;
        let p_prev = self.nodes[p].prev;
        let p_next = self.nodes[p].next;
        self.area(m_prev, m, p_prev) < 0.0 && self.area(p_next, m, m_next) < 0.0
    }

    /// Interlinks polygon nodes in z-order.
    fn index_curve(&mut self, start: usize) {
        let mut p = start;

        loop {
            if self.nodes[p].z == 0 {
                let (x, y) = (self.nodes[p].x, self.nodes[p].y);
                self.nodes[p].z = self.z_order(x, y);
            }
            self.nodes[p].prev_z = self.nodes[p].prev;
            self.nodes[p].next_z = self.nodes[p].next;
            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }

        let prev_z = self.nodes[p].prev_z;
        self.nodes[prev_z].next_z = NONE;
        self.nodes[p].prev_z = NONE;

        self.sort_linked(p);
    }

    /// Simon Tatham's linked list merge sort algorithm, sorting by z-order.
    fn sort_linked(&mut self, list_in: usize) -> usize {
        let mut list = list_in;
        let mut in_size: usize = 1;

        loop {
            let mut p = list;
            list = NONE;
            let mut tail = NONE;
            let mut num_merges = 0;

            while p != NONE {
                num_merges += 1;
                let mut q = p;
                let mut p_size: usize = 0;
                for _ in 0..in_size {
                    p_size += 1;
                    q = self.nodes[q].next_z;
                    if q == NONE {
                        break;
                    }
                }

                let mut q_size = in_size;

                while p_size > 0 || (q_size > 0 && q != NONE) {
                    let e;
                    if p_size != 0
                        && (q_size == 0 || q == NONE || self.nodes[p].z <= self.nodes[q].z)
                    {
                        e = p;
                        p = self.nodes[p].next_z;
                        p_size -= 1;
                    } else {
                        e = q;
                        q = self.nodes[q].next_z;
                        q_size -= 1;
                    }

                    if tail != NONE {
                        self.nodes[tail].next_z = e;
                    } else {
                        list = e;
                    }

                    self.nodes[e].prev_z = tail;
                    tail = e;
                }

                p = q;
            }

            if tail != NONE {
                self.nodes[tail].next_z = NONE;
            }

            if num_merges <= 1 {
                return list;
            }

            in_size *= 2;
        }
    }

    /// Z-order of a point given the coords of the containing bbox.
    fn z_order(&self, x_: f64, y_: f64) -> i32 {
        // Coords are transformed into non-negative 15-bit integer range.
        let mut x = ((x_ - self.min_x) * self.inv_size) as i32;
        let mut y = ((y_ - self.min_y) * self.inv_size) as i32;

        x = (x | (x << 8)) & 0x00FF00FF;
        x = (x | (x << 4)) & 0x0F0F0F0F;
        x = (x | (x << 2)) & 0x33333333;
        x = (x | (x << 1)) & 0x55555555;

        y = (y | (y << 8)) & 0x00FF00FF;
        y = (y | (y << 4)) & 0x0F0F0F0F;
        y = (y | (y << 2)) & 0x33333333;
        y = (y | (y << 1)) & 0x55555555;

        x | (y << 1)
    }

    /// Finds the leftmost node of a polygon ring.
    fn get_leftmost(&self, start: usize) -> usize {
        let mut p = start;
        let mut leftmost = start;
        loop {
            if self.nodes[p].x < self.nodes[leftmost].x
                || (self.nodes[p].x == self.nodes[leftmost].x
                    && self.nodes[p].y < self.nodes[leftmost].y)
            {
                leftmost = p;
            }
            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }
        leftmost
    }

    /// Checks if a diagonal between two polygon nodes is valid (lies in the
    /// polygon interior).
    fn is_valid_diagonal(&self, a: usize, b: usize) -> bool {
        let a_next = self.nodes[a].next;
        let a_prev = self.nodes[a].prev;
        let b_prev = self.nodes[b].prev;
        let b_next = self.nodes[b].next;

        self.nodes[a_next].i != self.nodes[b].i
            && self.nodes[a_prev].i != self.nodes[b].i
            && !self.intersects_polygon(a, b)
            && ((self.locally_inside(a, b)
                && self.locally_inside(b, a)
                && self.middle_inside(a, b)
                // Does not create opposite-facing sectors.
                && (self.area(a_prev, a, b_prev) != 0.0 || self.area(a, b_prev, b) != 0.0))
                // Special zero-length case.
                || (self.equals(a, b)
                    && self.area(a_prev, a, a_next) > 0.0
                    && self.area(b_prev, b, b_next) > 0.0))
    }

    /// Signed area of a triangle.
    #[inline]
    fn area(&self, p: usize, q: usize, r: usize) -> f64 {
        let (px, py) = (self.nodes[p].x, self.nodes[p].y);
        let (qx, qy) = (self.nodes[q].x, self.nodes[q].y);
        let (rx, ry) = (self.nodes[r].x, self.nodes[r].y);
        (qy - py) * (rx - qx) - (qx - px) * (ry - qy)
    }

    /// Checks if two points are equal.
    #[inline]
    fn equals(&self, p1: usize, p2: usize) -> bool {
        self.nodes[p1].x == self.nodes[p2].x && self.nodes[p1].y == self.nodes[p2].y
    }

    /// Checks if two segments intersect.
    fn intersects(&self, p1: usize, q1: usize, p2: usize, q2: usize) -> bool {
        let o1 = sign(self.area(p1, q1, p2));
        let o2 = sign(self.area(p1, q1, q2));
        let o3 = sign(self.area(p2, q2, p1));
        let o4 = sign(self.area(p2, q2, q1));

        if o1 != o2 && o3 != o4 {
            return true; // general case
        }

        // p1, q1 and p2 are colinear and p2 lies on p1q1.
        if o1 == 0 && self.on_segment(p1, p2, q1) {
            return true;
        }
        // p1, q1 and q2 are colinear and q2 lies on p1q1.
        if o2 == 0 && self.on_segment(p1, q2, q1) {
            return true;
        }
        // p2, q2 and p1 are colinear and p1 lies on p2q2.
        if o3 == 0 && self.on_segment(p2, p1, q2) {
            return true;
        }
        // p2, q2 and q1 are colinear and q1 lies on p2q2.
        if o4 == 0 && self.on_segment(p2, q1, q2) {
            return true;
        }

        false
    }

    /// For colinear points p, q, r, checks if point q lies on segment pr.
    fn on_segment(&self, p: usize, q: usize, r: usize) -> bool {
        let (px, py) = (self.nodes[p].x, self.nodes[p].y);
        let (qx, qy) = (self.nodes[q].x, self.nodes[q].y);
        let (rx, ry) = (self.nodes[r].x, self.nodes[r].y);
        qx <= fmax(px, rx) && qx >= fmin(px, rx) && qy <= fmax(py, ry) && qy >= fmin(py, ry)
    }

    /// Checks if a polygon diagonal intersects any polygon segments.
    fn intersects_polygon(&self, a: usize, b: usize) -> bool {
        let mut p = a;
        loop {
            let next = self.nodes[p].next;
            if self.nodes[p].i != self.nodes[a].i
                && self.nodes[next].i != self.nodes[a].i
                && self.nodes[p].i != self.nodes[b].i
                && self.nodes[next].i != self.nodes[b].i
                && self.intersects(p, next, a, b)
            {
                return true;
            }
            p = next;
            if p == a {
                break;
            }
        }
        false
    }

    /// Checks if a polygon diagonal is locally inside the polygon.
    fn locally_inside(&self, a: usize, b: usize) -> bool {
        let a_prev = self.nodes[a].prev;
        let a_next = self.nodes[a].next;
        if self.area(a_prev, a, a_next) < 0.0 {
            self.area(a, b, a_next) >= 0.0 && self.area(a, a_prev, b) >= 0.0
        } else {
            self.area(a, b, a_prev) < 0.0 || self.area(a, a_next, b) < 0.0
        }
    }

    /// Checks if the middle vertex of a polygon diagonal is inside the polygon.
    fn middle_inside(&self, a: usize, b: usize) -> bool {
        let mut p = a;
        let mut inside = false;
        let px_mid = (self.nodes[a].x + self.nodes[b].x) / 2.0;
        let py_mid = (self.nodes[a].y + self.nodes[b].y) / 2.0;
        loop {
            let next = self.nodes[p].next;
            let (px, py) = (self.nodes[p].x, self.nodes[p].y);
            let (nx, ny) = (self.nodes[next].x, self.nodes[next].y);
            if ((py > py_mid) != (ny > py_mid))
                && ny != py
                && (px_mid < (nx - px) * (py_mid - py) / (ny - py) + px)
            {
                inside = !inside;
            }
            p = next;
            if p == a {
                break;
            }
        }
        inside
    }

    /// Links two polygon vertices with a bridge; if the vertices belong to the
    /// same ring, it splits the polygon into two. If one belongs to the outer
    /// ring and another to a hole, it merges it into a single ring.
    fn split_polygon(&mut self, a: usize, b: usize) -> usize {
        let a2 = {
            let n = self.nodes[a];
            self.nodes.construct(n.i, n.x, n.y)
        };
        let b2 = {
            let n = self.nodes[b];
            self.nodes.construct(n.i, n.x, n.y)
        };
        let an = self.nodes[a].next;
        let bp = self.nodes[b].prev;

        self.nodes[a].next = b;
        self.nodes[b].prev = a;

        self.nodes[a2].next = an;
        self.nodes[an].prev = a2;

        self.nodes[b2].next = a2;
        self.nodes[a2].prev = b2;

        self.nodes[bp].next = b2;
        self.nodes[b2].prev = bp;

        b2
    }

    /// Creates a node and optionally links it with the previous one (in a
    /// circular doubly linked list).
    fn insert_node(&mut self, i: u32, pt: Point, last: usize) -> usize {
        let p = self.nodes.construct(i, pt[0], pt[1]);

        if last == NONE {
            self.nodes[p].prev = p;
            self.nodes[p].next = p;
        } else {
            let last_next = self.nodes[last].next;
            self.nodes[p].next = last_next;
            self.nodes[p].prev = last;
            self.nodes[last_next].prev = p;
            self.nodes[last].next = p;
        }
        p
    }

    /// Unlinks a node from both the ring and the z-order list, leaving the
    /// node's own links untouched so callers can still walk off it.
    fn remove_node(&mut self, p: usize) {
        let next = self.nodes[p].next;
        let prev = self.nodes[p].prev;
        self.nodes[next].prev = prev;
        self.nodes[prev].next = next;

        let prev_z = self.nodes[p].prev_z;
        let next_z = self.nodes[p].next_z;
        if prev_z != NONE {
            self.nodes[prev_z].next_z = next_z;
        }
        if next_z != NONE {
            self.nodes[next_z].prev_z = prev_z;
        }
    }
}

#[allow(clippy::too_many_arguments)]
#[inline]
fn point_in_triangle(
    ax: f64,
    ay: f64,
    bx: f64,
    by: f64,
    cx: f64,
    cy: f64,
    px: f64,
    py: f64,
) -> bool {
    (cx - px) * (ay - py) - (ax - px) * (cy - py) >= 0.0
        && (ax - px) * (by - py) - (bx - px) * (ay - py) >= 0.0
        && (bx - px) * (cy - py) - (cx - px) * (by - py) >= 0.0
}

#[inline]
fn sign(val: f64) -> i32 {
    (0.0 < val) as i32 - (val < 0.0) as i32
}

/// `std::min<double>` semantics: returns `b` only when `b < a`.
#[inline]
fn fmin(a: f64, b: f64) -> f64 {
    if b < a {
        b
    } else {
        a
    }
}

/// `std::max<double>` semantics: returns `b` only when `a < b`.
#[inline]
fn fmax(a: f64, b: f64) -> f64 {
    if a < b {
        b
    } else {
        a
    }
}

