//! Generation of the gear-shaped test polygon.

use crate::earcut::Point;

/// Builds the `n`-toothed gear ring: for every tooth, one vertex on the unit
/// circle followed by one vertex at radius 0.7, offset by half a step.
///
/// Mirrors the C++ loop exactly, including the order of the floating point
/// operations, so the coordinates are bit-identical.
pub fn gear_ring(n: i32) -> Vec<Point> {
    let mut gear: Vec<Point> = Vec::new();

    let mut i: i32 = 0;
    while i < n {
