//! Command line helpers.

/// Reimplementation of C's `atoi`: skips leading whitespace, accepts an
/// optional sign, consumes digits until the first non-digit, and yields 0 when
/// no digits are present.
///
/// Out-of-range input follows the glibc behaviour on 64-bit targets, where
/// `atoi` is `(int)strtol(...)`: the value saturates at the `long` limits and
/// is then truncated to `int`.
pub fn atoi(s: &str) -> i32 {
    let bytes = s.as_bytes();
    let mut i = 0;

    while i < bytes.len() && matches!(bytes[i], b' ' | b'\t' | b'\n' | b'\x0b' | b'\x0c' | b'\r') {
        i += 1;
    }

    let negative = match bytes.get(i) {
        Some(b'-') => {
            i += 1;
            true
        }
        Some(b'+') => {
            i += 1;
            false
        }
        _ => false,
    };

    let mut value: i64 = 0;
    let mut saturated = false;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        let digit = i64::from(bytes[i] - b'0');
        if !saturated {
            match value.checked_mul(10).and_then(|v| v.checked_add(digit)) {
                Some(v) => value = v,
                None => saturated = true,
            }
        }
        i += 1;
    }

    if saturated {
        value = if negative { i64::MIN } else { i64::MAX };
    } else if negative {
        value = -value;
    }

    value as i32
}

