#[cfg(test)]
mod tests {
    use super::*;

    /// Total area covered by the emitted triangles.
    fn triangulated_area(polygon: &[Vec<Point>], indices: &[u32]) -> f64 {
        let flat: Vec<Point> = polygon.iter().flatten().copied().collect();
        let mut sum = 0.0;
        for t in indices.chunks(3) {
            let (a, b, c) = (
                flat[t[0] as usize],
                flat[t[1] as usize],
                flat[t[2] as usize],
            );
            sum += ((b[0] - a[0]) * (c[1] - a[1]) - (c[0] - a[0]) * (b[1] - a[1])).abs() / 2.0;
        }
        sum
    }

    #[test]
    fn square_is_two_triangles() {
        let polygon = vec![vec![[0.0, 0.0], [10.0, 0.0], [10.0, 10.0], [0.0, 10.0]]];
        let indices = earcut(&polygon);
        assert_eq!(indices.len(), 6);
        assert!((triangulated_area(&polygon, &indices) - 100.0).abs() < 1e-9);
    }

    #[test]
    fn square_with_square_hole() {
        let polygon = vec![
            vec![[0.0, 0.0], [10.0, 0.0], [10.0, 10.0], [0.0, 10.0]],
            vec![[3.0, 3.0], [3.0, 7.0], [7.0, 7.0], [7.0, 3.0]],
        ];
        let indices = earcut(&polygon);
        // Eight vertices with one hole: 8 + 2 * 1 - 2 = 8 triangles.
        assert_eq!(indices.len(), 8 * 3);
        assert!((triangulated_area(&polygon, &indices) - (100.0 - 16.0)).abs() < 1e-9);
        assert!(indices.iter().all(|&i| i < 8));
    }

    #[test]
    fn concave_ring() {
        // An L shape: six vertices, one of them reflex.
        let polygon = vec![vec![
            [0.0, 0.0],
            [6.0, 0.0],
            [6.0, 2.0],
            [2.0, 2.0],
            [2.0, 6.0],
            [0.0, 6.0],
        ]];
        let indices = earcut(&polygon);
        assert_eq!(indices.len(), 4 * 3);
        assert!((triangulated_area(&polygon, &indices) - 20.0).abs() < 1e-9);
    }

    #[test]
    fn degenerate_input_yields_nothing() {
        assert!(earcut(&[]).is_empty());
        assert!(earcut(&[vec![]]).is_empty());
        assert!(earcut(&[vec![[0.0, 0.0], [1.0, 1.0]]]).is_empty());
        // Colinear points enclose no area.
        assert!(earcut(&[vec![[0.0, 0.0], [1.0, 0.0], [2.0, 0.0]]]).is_empty());
    }

    #[test]
    fn winding_order_does_not_matter() {
        let ccw = vec![vec![[0.0, 0.0], [10.0, 0.0], [10.0, 10.0], [0.0, 10.0]]];
        let cw = vec![vec![[0.0, 10.0], [10.0, 10.0], [10.0, 0.0], [0.0, 0.0]]];
        assert_eq!(earcut(&ccw).len(), earcut(&cw).len());
        assert!((triangulated_area(&cw, &earcut(&cw)) - 100.0).abs() < 1e-9);
    }

    #[test]
    fn hashed_path_matches_plain_path() {
        // More than 80 vertices switches the z-order hashing on; a circle is
        // convex, so the triangle count is fixed regardless of the code path.
        let n = 200;
        let ring: Vec<Point> = (0..n)
            .map(|i| {
                let a = 2.0 * std::f64::consts::PI * (i as f64) / (n as f64);
                [a.cos(), a.sin()]
            })
            .collect();
        let polygon = vec![ring];
        let indices = earcut(&polygon);
        assert_eq!(indices.len(), (n - 2) * 3);
        // Area of a regular n-gon inscribed in the unit circle.
        let expected = 0.5 * (n as f64) * (2.0 * std::f64::consts::PI / (n as f64)).sin();
        assert!((triangulated_area(&polygon, &indices) - expected).abs() < 1e-9);
    }
}

